#!/bin/bash
# Qwen3-Omni-30B-A3B-Instruct (thinker) DFlash draft training on TEXT data
# (open-perfectblend regenerated by the omni thinker), block_size=8.
#
# Pure DP: one full ~59 GiB bf16 thinker per GPU, HF backend (the omni thinker
# is a *ConditionalGeneration model that neither AutoModelForCausalLM nor the
# sglang backend can wire for capture, so train_dflash.py loads the thinker
# directly for the qwen3_omni_moe text path — see build_models()).
#
#   full run:  bash examples/run_qwen3_omni_dflash_text.sh
#   smoke:     SMOKE=1 bash examples/run_qwen3_omni_dflash_text.sh
#   resume:    RESUME=1 bash examples/run_qwen3_omni_dflash_text.sh
set -euo pipefail

SCRIPT_DIR=$( cd -- "$( dirname -- "${BASH_SOURCE[0]}" )" &> /dev/null && pwd )
ROOT_DIR=$(dirname "$SCRIPT_DIR")
cd "$ROOT_DIR"
source "$ROOT_DIR/.venv/bin/activate"

# sdpa backend => flash_attn not required. Dynamo off + single-thread BLAS
# mirror the proven omni recipe.
export TORCHDYNAMO_DISABLE=1
export OMP_NUM_THREADS=1
export MKL_NUM_THREADS=1
export OPENBLAS_NUM_THREADS=1
export TOKENIZERS_PARALLELISM=false
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export SPECFORGE_DATA_NUM_PROC=${SPECFORGE_DATA_NUM_PROC:-16}

NUM_GPUS=${NUM_GPUS:-8}
BLOCK_SIZE=${BLOCK_SIZE:-8}
NUM_EPOCHS=${NUM_EPOCHS:-6}
LR=${LR:-6e-4}
WARMUP_RATIO=${WARMUP_RATIO:-0.04}
MAX_LENGTH=${MAX_LENGTH:-3072}
DIST_TIMEOUT=${DIST_TIMEOUT:-14400}
TARGET_MODEL=${TARGET_MODEL:-/workspace_yuekai/HF/Qwen3-Omni-30B-A3B-Instruct}
TRAIN_DATA=${TRAIN_DATA:-/workspace_yuekai/speculative/DeepSpec/train_datasets/qwen3_omni_30b_a3b_instruct/perfectblend_train_regen.jsonl}
OUTPUT_DIR=${OUTPUT_DIR:-outputs/qwen3-omni-30b-dflash-text-bs${BLOCK_SIZE}}
WANDB_NAME=${WANDB_NAME:-omni-perfectblend-dflash-bs${BLOCK_SIZE}-ep${NUM_EPOCHS}}
RESUME_ARG=""; [ "${RESUME:-0}" = "1" ] && RESUME_ARG="--resume"
MAX_STEPS_ARG=""

if [ "${SMOKE:-0}" = "1" ]; then
  TRAIN_DATA=$ROOT_DIR/cache/dataset/perfectblend_regen_smoke64.jsonl
  MAX_STEPS_ARG="--max-num-steps 2"
  OUTPUT_DIR=outputs/qwen3-omni-30b-dflash-text-smoke
  WANDB_NAME=omni-text-dflash-smoke
  NUM_EPOCHS=1
  DIST_TIMEOUT=1200
fi

# Use `python -m torch.distributed.run` (not the `torchrun` shim, whose
# /usr/bin/python3 shebang would spawn workers in the SYSTEM interpreter where
# the venv deps like `accelerate` are absent) so workers inherit this venv.
python -m torch.distributed.run --standalone --nproc_per_node "$NUM_GPUS" scripts/train_dflash.py \
  --target-model-path "$TARGET_MODEL" \
  --draft-config-path configs/qwen3-omni-30b-dflash-bs8.json \
  --train-data-path "$TRAIN_DATA" \
  --output-dir "$OUTPUT_DIR" \
  --chat-template qwen \
  --target-model-backend hf \
  --embedding-key thinker.model.embed_tokens.weight \
  --lm-head-key thinker.lm_head.weight \
  --mask-token-id 151662 \
  --attention-backend sdpa \
  --block-size "$BLOCK_SIZE" \
  --num-anchors 512 \
  --batch-size ${BATCH_SIZE:-1} \
  --max-length "$MAX_LENGTH" \
  --learning-rate "$LR" \
  --warmup-ratio "$WARMUP_RATIO" \
  --max-grad-norm 1.0 \
  --loss-decay-gamma 7.0 \
  --num-epochs "$NUM_EPOCHS" \
  --dist-timeout "$DIST_TIMEOUT" \
  --build-dataset-num-proc ${BUILD_NUM_PROC:-16} \
  --log-interval ${LOG_INTERVAL:-50} \
  --save-interval ${SAVE_INTERVAL:-1000} \
  $RESUME_ARG \
  $MAX_STEPS_ARG \
  --report-to wandb \
  --wandb-project qwen3omni-dflash-text \
  --wandb-name "$WANDB_NAME"
